head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDBNF05010";
scwin.rownum = 1;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — gubun

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_datefmt_cal_intPayDd1();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf05010.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "cal_intPayDd1", fn: function () { return String(String((dma_pageContext.get("intPayDd1") ?? ""))); } },
        { childId: "ipt_redmptAmt1", fn: function () { return String(String((dma_pageContext.get("redmptAmt1") ?? ""))); } },
        { childId: "ipt_coupnRt1", fn: function () { return String(String((dma_pageContext.get("coupnRt1") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_datefmt_cal_intPayDd1
 * @description 초기화 — datefmt cal int Pay Dd1
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_intPayDd1 = function () { $c.date.checkCalendarFormat("cal_intPayDd1", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.makeInputFromParent($, {  });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05010.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldbnf05010: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_addRow_onclick
 * @description btn_addRow 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_addRow_onclick = function(e){
    try {
        scwin.addRow()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05010.btn_addRow_onclick' }); }
};

/**
 * @method
 * @name btn_delRow_onclick
 * @description btn_delRow 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delRow_onclick = async function(e){
    try {
        await scwin.delRow()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05010.btn_delRow_onclick' }); }
};

/**
 * @method
 * @name ipt_redmptAmt1_onpaste
 * @description ipt_redmptAmt1 onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_redmptAmt1_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05010.ipt_redmptAmt1_onpaste' }); }
};

/**
 * @method
 * @name ipt_coupnRt1_onpaste
 * @description ipt_coupnRt1 onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_coupnRt1_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05010.ipt_coupnRt1_onpaste' }); }
};

/**
 * @method
 * @name btn_divSendForm_onclick
 * @description btn_divSendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_divSendForm_onclick = async function(e){
    try {
        await scwin.div_send_form('__self.form',(String(((dma_pageContext.get("gubun") ?? "")) == null ? '' : ((dma_pageContext.get("gubun") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("gubun") ?? "")) == null ? '' : ((dma_pageContext.get("gubun") ?? "")))))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05010.btn_divSendForm_onclick' }); }
};

/**
 * @method
 * @name btn_divSendClose_onclick
 * @description btn_divSendClose 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_divSendClose_onclick = function(e){
    try {
        scwin.div_send_close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05010.btn_divSendClose_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name NumberCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.NumberCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^0-9]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name DemicalNumberCheck
 * @description Demical Number Check 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.DemicalNumberCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^0-9.]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name DemicalCheck
 * @description Demical Check 처리
 * @param {Object} obj 컴포넌트
 * @param {*} a a
 * @param {*} b b
 * @returns {void}
 * @hidden N
 */
scwin.DemicalCheck = function (obj, a, b) { try { if (!obj || obj.value == null) { return; } const dec = (b === undefined) ? a : b; const v = String(obj.value).replace(/[^\d.]/g, ''); const p = v.split('.'); let i = p.shift() || ''; let d = p.join(''); if (b !== undefined && a > 0) { i = i.substring(0, a); } if (dec >= 0) { d = d.substring(0, dec); } obj.value = i + (v.indexOf('.') >= 0 && dec > 0 ? '.' + d : ''); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name cal_offMask
 * @description cal off Mask 처리
 * @returns {void}
 * @hidden N
 */
scwin.cal_offMask = function () { /* 등가 no-op — to-be 필드 마스크 미사용 */ };

/**
 * @method
 * @name chkDate
 * @description chk Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkDate = function () { /* 등가 no-op — 날짜 형식은 inputCalendar·제출 검증 몫 */ };

/**
 * @method
 * @name addRow
 * @description add Row 처리
 * @returns {void}
 * @hidden N
 */
scwin.addRow = function () {
    const rowPlus = $c.util.getComponent("tbl_non_eq");
    let tr;
    let th;
    let td;
    const newRowNum = scwin.rownum + 1;
    const $tblNonEq = $('#tbl_non_eq');
    const $tr = $("<tr></tr>");
    const $td1 = $("<td>" + newRowNum + "</td>").addClass('first txc');
    const $td2 = $("<td><div style=\"display:flex; align-items:center;\"><input type=\"text\" id=\"int_pay_dd_" + newRowNum + "\" name=\"int_pay_dd_" + newRowNum + "\" value=\"\" maxlength=8 class=\"txt input-calendar\" style=\"height: 24px;\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'이자지급일 " + newRowNum + "차' )\" onfocus=\"cal_offMask('document.InputForm.int_pay_dd_" + newRowNum + "')\" onkeyup=\"chkDate('document.InputForm.int_pay_dd_" + newRowNum + "')\" /></div></td>");
    const $td3 = $("<td><input type=\"text\" name=\"redmpt_amt_" + newRowNum + "\"  value=\"\" maxlength=18 class=\"txt short\" style=\"text-align: right;IME-MODE:disabled;\" onkeypress=\"NumberCheck(this)\" onFocus=\'Del_MoneyComma(this);\' onBlur=\'Add_MoneyComma(this);\' /> 원</td>");
    const $td4 = $("<td><input type=\"text\" name=\"coupn_rt_" + newRowNum + "\"  value=\"\" maxlength=8 class=\"txt short\" style=\"text-align: right;IME-MODE:disabled;\" onkeypress=\"DemicalNumberCheck(this)\" onkeyup=\"DemicalCheck(this,2,5)\" /> %</td>");
    const $td5 = $("<td><select name=\"redmpt_pd_int_tp_cd_" + newRowNum + "\"><option value=\"0\"></option><option value=\"1\">단리</option><option value=\"2\">복리</option><option value=\"3\">이표채</option></select></td>");
    $tr.append($td1);
    $tr.append($td2);
    $tr.append($td3);
    $tr.append($td4);
    $tr.append($td5);
    $tblNonEq.append($tr);
    scwin.rownum++;
    $("#int_pay_dd_" + newRowNum).datepicker(myDateOpts);
};

/**
 * @method
 * @name delRow
 * @description del Row 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delRow = async function () {
    const rowPlus = $c.util.getComponent("tbl_non_eq");
    if (scwin.rownum > 0) {
        const no = rowPlus.rows.length - 1;
        rowPlus.deleteRow(no);
        scwin.rownum--;
    } else {
        if (scwin.rownum < 1) {
            await $c.win.alert("삭제 할 행이 없습니다.");
        }
    }
};

/**
 * @method
 * @name makeInputFromParent
 * @description make Input From Parent 처리
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.makeInputFromParent = function (index) {

    const parentfm = ((scwin.openerScwin())["SendForm"] !== undefined ? (scwin.openerScwin())["SendForm"] : undefined);
    const fm = (document.InputForm || { elements: [] });
    if (parentfm.non_eq_count.value === '') {
        scwin.rownum = 0;
    } else {
        scwin.rownum = parseInt(parentfm.non_eq_count.value);
    }
    const rowPlus = $c.util.getComponent("tbl_non_eq");
    let tr;
    let th;
    let td;
    let temprow = 0;
    if (scwin.rownum > 0) {
        temprow = scwin.rownum;
        $("#tbl_non_eq tr").remove();
        scwin.rownum = 0;
        for (let i = 1; i < temprow + 1; i++) {
            scwin.addRow();
            if (temprow === 1) {
                $c.util.getComponent("fm.int_pay_dd_" + i).setValue(eval("parentfm.arr_int_pay_dd.value"));
                $c.util.getComponent("fm.redmpt_amt_" + i).setValue(eval("parentfm.arr_redmpt_amt.value"));
                $c.util.getComponent("fm.coupn_rt_" + i).setValue(eval("parentfm.arr_coupn_rt.value"));
                $c.util.getComponent("fm.redmpt_pd_int_tp_cd_" + i).setValue(eval("parentfm.arr_redmpt_pd_int_tp_cd.value"));
            } else {
                if (temprow > 1) {
                    $c.util.getComponent("fm.int_pay_dd_" + i).setValue(eval("parentfm.arr_int_pay_dd[" + (i - 1) + "].value"));
                    $c.util.getComponent("fm.redmpt_amt_" + i).setValue(eval("parentfm.arr_redmpt_amt[" + (i - 1) + "].value"));
                    $c.util.getComponent("fm.coupn_rt_" + i).setValue(eval("parentfm.arr_coupn_rt[" + (i - 1) + "].value"));
                    $c.util.getComponent("fm.redmpt_pd_int_tp_cd_" + i).setValue(eval("parentfm.arr_redmpt_pd_int_tp_cd[" + (i - 1) + "].value"));
                }
            }
        }
    } else {
        scwin.rownum = 1;
    }
};

/**
 * @method
 * @name div_send_form
 * @description div send form 처리
 * @param {*} fm fm
 * @param {Number} index index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.div_send_form = async function (fm, index) {
    const msg_str = "분할상환일을 입력하실경우 \n\r해당차수 분할상환일의 상환금액, 거치기간이자를  \n\r입력하셔야 됩니다. ";
    const msg_str1 = "해당차수의 분할상환일, 상환금액, 거치기간이자를  \n\r입력하셔야 됩니다. ";

    const parentfm = ((scwin.openerScwin())["SendForm"] !== undefined ? (scwin.openerScwin())["SendForm"] : undefined);
    fm = (document.InputForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('cal_intPayDd1').getValue()) === 0) {
        await $c.win.alert("1차 분할상환일을 입력하십시오.");
        $c.util.getComponent("cal_intPayDd1").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_redmptAmt1').getValue()) === 0) {
        await $c.win.alert("1차 상환금액을 입력하십시오.");
        $c.util.getComponent("ipt_redmptAmt1").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_coupnRt1').getValue()) === 0) {
        await $c.win.alert("1차 이자율을 입력하십시오.");
        $c.util.getComponent("ipt_coupnRt1").focus();
        return;
    }
    if (($c.util.getComponent('slc_redmptPdIntTpCd1').getSelectedIndex() === 0)) {
        await $c.win.alert("1차 거치기간이자를 선택하십시오.");
        $c.util.getComponent("slc_redmptPdIntTpCd1").focus();
        return;
    }
    k = 4;
    for (i = 1; i < scwin.rownum; i++) {
        if ($c.str.getByteLength(fm.elements[k].value) > 0) {
            if (($c.str.getByteLength(fm.elements[k+1].value) === 0) || (fm.elements[k+3].value === 0)) {
                await $c.win.alert(msg_str);
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        } else {
            if (($c.str.getByteLength(fm.elements[k+1].value) > 0) || ($c.str.getByteLength(fm.elements[k+3].value) > 0)) {
                await $c.win.alert(msg_str1);
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
        k = k + 4;
    }
    $("#tbl_non_eq tr", ((scwin.openerScwin())["document"] !== undefined ? (scwin.openerScwin())["document"] : undefined)).remove();
    $("input[name=non_eq_count]", ((scwin.openerScwin())["document"] !== undefined ? (scwin.openerScwin())["document"] : undefined)).val(scwin.rownum);
    let tr;
    let td;

    const arrRows = [];
    for (let i = 1; i < scwin.rownum + 1; i++) {
        arrRows.push({ arrIntPaySeq: i, arrIntPayDd: ((function (c) { return c && c.getValue ? c.getValue() : ''; })($c.util.getComponent('intPayDd' + i))), arrRedmptAmt: ((function (c) { return c && c.getValue ? c.getValue() : ''; })($c.util.getComponent('redmptAmt' + i))), arrCoupnRt: ((function (c) { return c && c.getValue ? c.getValue() : ''; })($c.util.getComponent('coupnRt' + i))), arrRedmptPdIntTpCd: ((function (c) { return c && c.getValue ? c.getValue() : ''; })($c.util.getComponent('redmptPdIntTpCd' + i))) });
    }
    /* TODO Stage2: [sdd] 배열 파라미터 표현 미정(전환 미완) — 부모창 «tbl_non_eq» 로 보내던 키 [arrIntPaySeq, arrIntPayDd, arrRedmptAmt, arrCoupnRt, arrRedmptPdIntTpCd] · 행  arrRows.length 건 */
    await $c.win.alert('이 값을 부모 화면으로 보내는 방식을 아직 정하지 못했습니다(전환 미완) — 배열 파라미터 표현');

    parentfm.split_redmpt_tp_cd.value = index;
    parentfm.equiv_redmpt_val.value = '';
    parentfm.defr_mms.value = '';
    parentfm.redmpt_pd_int_tp_cd.value = '';
    parentfm.split_redmpt_cnt.value = '';
    parentfm.non_eq_save_yn.value = "Y";
    if (parentfm.redmpt_methd_tp_cd[0].checked) {
        parentfm.redmpt_methd_tp_cd[0].checked = false;
    }
    parent.$c.win.closePopup();
};

/**
 * @method
 * @name div_send_close
 * @description div send close 처리
 * @returns {void}
 * @hidden N
 */
scwin.div_send_close = function () {
    const parentfm = ((scwin.openerScwin())["SendForm"] !== undefined ? (scwin.openerScwin())["SendForm"] : undefined);
    if ($c.str.getByteLength(parentfm.split_redmpt_tp_cd.value) === 0) {
        parentfm.redmpt_methd_tp_cd[0].checked = true;
    } else {
        if (parentfm.split_redmpt_tp_cd.value === '1') {
            parentfm.redmpt_methd_tp_cd[1].checked = true;
        } else {
            if (parentfm.split_redmpt_tp_cd.value === '2') {
                parentfm.redmpt_methd_tp_cd[2].checked = true;
            } else {
                if (parentfm.split_redmpt_tp_cd.value === '3') {
                    parentfm.redmpt_methd_tp_cd[3].checked = true;
                }
            }
        }
    }
    $c.win.closePopup();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
